def calculate_ratio(N, f):
    """Calculates R = Sum(f_i^2) / Sum(j * f_j^2)"""
    sum_f2 = 0
    sum_j_f2 = 0
    for i in range(1, N + 1):
        f_i = f[i-1]
        sum_f2 += f_i**2
        sum_j_f2 += i * f_i**2

    if sum_j_f2 == 0:
        return float('inf')
    return sum_f2 / sum_j_f2

# --- Case 1: Constant Sequence f_i = 1 ---
N_values = [3, 4, 5]
R_constant = {}
for N in N_values:
    f = [1] * N
    R_constant[N] = calculate_ratio(N, f)

# --- Case 2: Arithmetic Progression f_i = N - i + 1 ---
R_ap_rev = {}
for N in N_values:
    # f_i = N - i + 1 (i=1 -> N, i=N -> 1)
    f = [N - i + 1 for i in range(1, N + 1)]
    R_ap_rev[N] = calculate_ratio(N, f)

print("--- Constant Sequence Ratios ---")
for N, R in R_constant.items():
    print(f"N={N}: R = {R}")

print("\n--- AP Sequence (Reversed) Ratios ---")
for N, R in R_ap_rev.items():
    print(f"N={N}: R = {R}")
